INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000005b',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about quantity and measurement in Hindi","Use kitna/kitni for how much/how many","Express weights and measures"],"explanation":{"intro":"Quantity and measurement vocabulary covers how to ask and answer questions about amounts, weights, and distances in Hindi.","culturalNote":"Measurements in India: India officially uses the metric system (SI units). However, traditional units persist: seer (ser = approx 1kg — still used in fruit/vegetable markets), tola (gold measurement — approx 11.66g), bigha (land measurement — varies by state), kos (distance — obsolete), inch/foot still common in construction and height. Markets: sabzi mandi (vegetable market) — vegetables sold by kilo. Grain: sold by kilo or quintal (100kg). Gold: sold by tola or gram. Milk: sold by litre. Cloth: sold by metre. Key question: kitne ka? (how much does it cost? — kitna + ka, asked about price). Kilo (kilo), litre (litre), metre (metre), gram (gram) — all borrowed internationally."},"examples":[{"sentence":"Ek kilo tamatar kitne ka hai?","english":"How much is one kilo of tomatoes?"},{"sentence":"Mujhe do litre doodh chahiye.","english":"I need two litres of milk."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about quantity and measurement in Hindi."}}',
'{"items":[{"word":"kitna/kitni","translation":"how much/how many (m/f)","transliteration":"kitna/kitni","pronunciation":"KIT-na/KIT-ni","example":"kitna chahiye"},{"word":"kilo","translation":"kilogram","transliteration":"kilo","pronunciation":"KI-lo","example":"ek kilo"},{"word":"litre","translation":"litre","transliteration":"litre","pronunciation":"LEE-tar","example":"do litre"},{"word":"thoda","translation":"a little/a bit","transliteration":"thoda","pronunciation":"THO-da","example":"thoda aur"},{"word":"zyada","translation":"more/a lot","transliteration":"zyada","pronunciation":"ZYAA-da","example":"zyada nahi"},{"word":"kaafi","translation":"enough/quite","transliteration":"kaafi","pronunciation":"KAA-fee","example":"kaafi hai"}]}',
'{"title":"Kitna/Kitni X chahiye — How much/many X is needed? (quantity question)","pattern":"Kitna X chahiye? (masculine X) / Kitni X chahiye? (feminine X) = How much X is needed? Kitna agrees with the noun (masculine/feminine). Kitne = plural (kitne log = how many people). chahiye = is needed (invariant). Answering: ek kilo chahiye (one kilo is needed), thoda chahiye (a little is needed), kaafi hai (there is enough).","explanation":"Quantity questions: kitna (m), kitni (f), kitne (pl). Kitna doodh chahiye? = How much milk is needed? Kitni roti chahiye? = How many rotis are needed? Kitne aadmi hain? = How many men are there? Note: kitna also asks about price: kitne ka? = how much does it cost? (kitne + ka = of how much). Answers use numbers + unit: do kilo (two kilos), teen litre (three litres), paanch metre (five metres). Quantity adverbs: thoda (a little), zyada (more/a lot), kaafi (enough/quite), bahut (very/a lot), sirf (only), bas (just/enough).","examples":[{"sentence":"Kitni cheeni chahiye chai mein?","english":"How much sugar is needed in the tea?"},{"sentence":"Sirf ek kilo kaafi hai.","english":"Only one kilo is enough."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kaafi means?","options":["enough/quite","more","less","exactly"],"correctAnswer":"enough/quite"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"How much is one kilo of tomatoes?","options":["Ek kilo tamatar kitne ka hai?","Do kilo tamatar kitne ka hai?","Ek kilo aalu kitne ka hai?","Ek kilo tamatar kitni ka hai?"],"correctAnswer":"Ek kilo tamatar kitne ka hai?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kitni cheeni chahiye chai ___ ?","options":["mein","ko","se","par"],"correctAnswer":"mein"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I need two litres of milk.","wordBankItems":["Mujhe","do","litre","doodh","chahiye","."],"correctAnswer":"Mujhe do litre doodh chahiye ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"thoda means?","options":["a little/a bit","a lot","enough","none"],"correctAnswer":"a little/a bit"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000005c',1,'APPROVED','PUBLISHED',
'{"objectives":["Express extended likes and dislikes in Hindi","Use mujhe X achha lagta/lagti hai for liking","Discuss preferences with reasons"],"explanation":{"intro":"Extended likes and dislikes vocabulary covers a wider range of preferences — music, places, seasons, people — and how to explain why you like or dislike something.","culturalNote":"Preference expression in India: sharing opinions about Bollywood films, cricket players, food, and politicians is universal conversation currency. Favourite (pasandida) is a very commonly asked question: tumhara pasandida khiladi kaun hai? (who is your favourite player?). Pasandida film? pasandida gaana? pasandida khana? — these open up conversations effortlessly. Indian social conversations frequently centre on sharing preferences about entertainment, food, and family. Arguing about preferences is also common — especially about cricket (Virat Kohli vs MS Dhoni debates are endless). Key phrase: mujhe yeh bahut accha lagta hai (I really like this — lit. this seems very good to me). Negative: mujhe yeh pasand nahi (I don''t like this)."},"examples":[{"sentence":"Mujhe pahadi jagahein bahut acchi lagti hain.","english":"I really like hilly places."},{"sentence":"Mujhe monsoon ka mausam pasand hai kyunki hawa thandi hoti hai.","english":"I like the monsoon season because the air is cool."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express extended likes, dislikes, and preferences in Hindi with reasons."}}',
'{"items":[{"word":"pasandida","translation":"favourite","transliteration":"pasandida","pronunciation":"pa-san-DEE-da","example":"mera pasandida"},{"word":"achha lagna","translation":"to seem good / to like","transliteration":"achha lagna","pronunciation":"ACH-cha LAG-na","example":"mujhe achha lagta hai"},{"word":"bura lagna","translation":"to seem bad / to dislike","transliteration":"bura lagna","pronunciation":"BU-ra LAG-na","example":"mujhe bura lagta hai"},{"word":"dilchasp","translation":"interesting","transliteration":"dilchasp","pronunciation":"dil-CHASP","example":"dilchasp kitab"},{"word":"boriyat","translation":"boredom","transliteration":"boriyat","pronunciation":"bo-ri-YAT","example":"boriyat hona"},{"word":"mazedar","translation":"fun/enjoyable","transliteration":"mazedar","pronunciation":"ma-ze-DAR","example":"mazedar khel"}]}',
'{"title":"Mujhe X achha/bura lagta/lagti hai — I like/dislike X (lagna for emotional response)","pattern":"Mujhe X achha lagta hai = I like X / X seems good to me. Mujhe X bura lagta hai = I dislike X. lagta = masculine (for masculine X or activities). lagti = feminine (for feminine X). Dative subject: mujhe (to me). X = the liked/disliked item. This construction expresses subjective liking more naturally than pasand in many contexts.","explanation":"Lagna for subjective response: mujhe X achha/bura/dilchasp/boring lagta/lagti hai. Agreement: lagta (for masculine X or abstract activities), lagti (for feminine X). Mujhe cricket achha lagta hai (I like cricket — cricket is generally treated as masculine/invariant). Mujhe yeh film boring lagti hai (I find this film boring — film = feminine). More emphatic: bahut achha lagta hai (I really like it). lagna also: mujhe cold lag raha hai (I''m feeling cold — physical sensation). Mujhe dard lag raha hai (I''m feeling pain).","examples":[{"sentence":"Mujhe classical music bahut dilchasp lagti hai.","english":"I find classical music very interesting."},{"sentence":"Usse yeh kaam boring lagta hai.","english":"He/she finds this work boring."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"mazedar means?","options":["fun/enjoyable","interesting","good","pleasant"],"correctAnswer":"fun/enjoyable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I really like hilly places.","options":["Mujhe pahadi jagahein bahut acchi lagti hain.","Mujhe pahadi jagahein bahut acchi lagta hai.","Mujhe tatoori jagahein bahut acchi lagti hain.","Mujhe pahadi jagahein thodi acchi lagti hain."],"correctAnswer":"Mujhe pahadi jagahein bahut acchi lagti hain."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mujhe classical music bahut dilchasp ___ hai.","options":["lagti","lagta","lage","lag rahi"],"correctAnswer":"lagti"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I like the monsoon season because the air is cool.","wordBankItems":["Mujhe","monsoon","ka","mausam","pasand","hai","kyunki","hawa","thandi","hoti","hai","."],"correctAnswer":"Mujhe monsoon ka mausam pasand hai kyunki hawa thandi hoti hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"pasandida means?","options":["favourite","liked","preferred","popular"],"correctAnswer":"favourite"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000005d',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about health habits in Hindi","Use roz X karna for daily health routines","Discuss exercise and wellness"],"explanation":{"intro":"Health habits vocabulary covers daily wellness routines — exercise, diet, sleep, and how to describe a healthy lifestyle in Hindi.","culturalNote":"Health and wellness in India: yoga (yog = yoga — India''s gift to the world — International Yoga Day June 21), ayurveda (traditional Indian medicine — herbs, diet, lifestyle), pranayama (breathing exercises), surya namaskar (sun salutation — 12-step yoga sequence). Health habits: subah ki sair (morning walk — extremely popular among middle-aged Indians in parks), doodh peena (drinking milk — strongly encouraged by parents), haldi doodh (turmeric milk = ''golden milk'' — natural immunity booster — trendy globally now), neem ki daatun (neem twig toothbrush — traditional). Diet: doctors recommend dal-chawal (lentils and rice) as the most balanced Indian diet. Gym: increasingly popular in cities — Cult.fit, Anytime Fitness. Mental health: awareness growing but stigma still significant. Meditation (dhyan = dhyana) practices from various traditions."},"examples":[{"sentence":"Main roz subah 30 minute exercise karta hoon.","english":"I exercise for 30 minutes every morning."},{"sentence":"Acchi sehat ke liye paryaapt neend zaroori hai.","english":"Adequate sleep is necessary for good health."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about daily health habits and wellness in Hindi."}}',
'{"items":[{"word":"sehat","translation":"health","transliteration":"sehat","pronunciation":"SE-hat","example":"acchi sehat"},{"word":"exercise","translation":"exercise","transliteration":"exercise","pronunciation":"EX-er-saiz","example":"roz exercise"},{"word":"neend","translation":"sleep","transliteration":"neend","pronunciation":"neend","example":"acchi neend"},{"word":"paryaapt","translation":"adequate/sufficient","transliteration":"paryaapt","pronunciation":"par-YAAPT","example":"paryaapt paani"},{"word":"sair","translation":"walk/stroll","transliteration":"sair","pronunciation":"sair","example":"subah ki sair"},{"word":"tandrust","translation":"healthy/fit","transliteration":"tandrust","pronunciation":"tan-DRUST","example":"tandrust rehna"}]}',
'{"title":"Roz X karna chahiye — One should do X daily (chahiye for advice/recommendation)","pattern":"Roz X karna chahiye = One should do X daily. Roz = daily/every day. chahiye = should/ought to (impersonal advice — no subject, or mujhe/tumhe/hame). Giving advice: X karna chahiye (one should do X). Personal: mujhe roz exercise karni chahiye (I should exercise daily — karni because exercise is often treated as feminine context).","explanation":"chahiye for advice and recommendation: X karna chahiye = one should do X (impersonal, general advice). Compare: mujhe X chahiye (I need/want X — desire) vs. X karna chahiye (one should do X — advice/recommendation). Health advice context: roz sair karna chahiye (one should take a daily walk), paani zyada peena chahiye (one should drink more water), junk food kam khaana chahiye (one should eat less junk food). Adding subject: tumhe roz yoga karna chahiye (you should do yoga daily — specific advice to someone). Negative: X nahi karna chahiye (one should not do X).","examples":[{"sentence":"Raat ko junk food nahi khaana chahiye.","english":"One should not eat junk food at night."},{"sentence":"Har roz do litre paani peena chahiye.","english":"One should drink two litres of water every day."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"sehat means?","options":["health","fitness","diet","exercise"],"correctAnswer":"health"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I exercise for 30 minutes every morning.","options":["Main roz subah 30 minute exercise karta hoon.","Main kabhi-kabhi subah 30 minute exercise karta hoon.","Main roz shaam 30 minute exercise karta hoon.","Main roz subah 1 ghanta exercise karta hoon."],"correctAnswer":"Main roz subah 30 minute exercise karta hoon."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Har roz do litre paani peena ___ .","options":["chahiye","chahiye hai","chahiye tha","chahiye hoga"],"correctAnswer":"chahiye"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Adequate sleep is necessary for good health.","wordBankItems":["Acchi","sehat","ke","liye","paryaapt","neend","zaroori","hai","."],"correctAnswer":"Acchi sehat ke liye paryaapt neend zaroori hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"sair means?","options":["walk/stroll","run","exercise","sport"],"correctAnswer":"walk/stroll"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000005e',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about family plans and events in Hindi","Use X ki shadi/birthday hai for family events","Discuss family milestones"],"explanation":{"intro":"Family plans vocabulary covers upcoming events — weddings, birthdays, anniversaries, and family get-togethers — and how to discuss them in Hindi.","culturalNote":"Family events in India: shaadi (wedding — most elaborate family event — days of ceremony — mehendi, sangeet, baraat, pheras, reception), birthday (birthday — increasingly celebrated Western-style — cake kaat na, candles — but also traditional: naam ke saath aashirwad lena = taking elders'' blessings). Anniversary (sawaarishk = shaadi ki saalgirah — wedding anniversary). Baby shower (godh bharaai = lap-filling ceremony — traditional Indian baby shower). Naming ceremony (naamkaran — naming the baby). Thread ceremony (upanayana — sacred thread ceremony for boys). New home (griha pravesh = house-entering ceremony — puja). Indian families track everyone''s events — invitations (shaadi ka card = wedding card — given in person as a mark of respect — not just digital). Joint family events mean large gatherings — 200-500 guests at a wedding is typical."},"examples":[{"sentence":"Agle mahine mere bhai ki shaadi hai.","english":"My brother''s wedding is next month."},{"sentence":"Kal meri maa ka birthday hai, hum cake laaenge.","english":"Tomorrow is my mother''s birthday, we will bring cake."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about upcoming family events and milestones in Hindi."}}',
'{"items":[{"word":"saalgirah","translation":"anniversary/birthday","transliteration":"saalgirah","pronunciation":"saal-gi-RAH","example":"saalgirah manaana"},{"word":"janam din","translation":"birthday","transliteration":"janam din","pronunciation":"JA-nam din","example":"janam din ki badhai"},{"word":"dawat","translation":"feast/invitation","transliteration":"dawat","pronunciation":"da-WAT","example":"dawat dena"},{"word":"mehman","translation":"guest","transliteration":"mehman","pronunciation":"meh-MAAN","example":"mehman aana"},{"word":"tyohaar","translation":"festival","transliteration":"tyohaar","pronunciation":"tyo-HAAR","example":"tyohaar manaana"},{"word":"aashirvaad","translation":"blessing","transliteration":"aashirvaad","pronunciation":"aa-SHEER-vaad","example":"aashirvaad lena"}]}',
'{"title":"X ka Y hai — X has Y / It is X''s Y (possession for events)","pattern":"X ka Y hai = It is X''s Y / X has Y. X ka / X ki / X ke = possessive of X (agrees with Y). Meri maa ka birthday hai = It is my mother''s birthday. Mere bhai ki shaadi hai = It is my brother''s wedding. ka/ki/ke agrees with Y: birthday (masculine) → ka. shaadi (feminine) → ki. kapde (masculine plural) → ke.","explanation":"Possessive for events: X ka/ki/ke Y hai = It is X''s Y. Very common for announcing upcoming events. The possessive must agree with Y (the event noun), not X (the person). Birthday = masculine → ka. Shaadi = feminine → ki. Exam = masculine → ka. Pariksha = feminine → ki. Party = feminine → ki. Marriage anniversary = saalgirah (feminine) → ki. Usage: announcements, invitations, reminders. Social necessity: telling people about upcoming family events is expected in Indian culture — not mentioning it would seem distant.","examples":[{"sentence":"Is hafte mere dost ki engagement hai.","english":"This week is my friend''s engagement."},{"sentence":"Kal hamare school ka annual function hai.","english":"Tomorrow is our school''s annual function."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"mehman means?","options":["guest","host","family","visitor"],"correctAnswer":"guest"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My brother''s wedding is next month.","options":["Agle mahine mere bhai ki shaadi hai.","Is mahine mere bhai ki shaadi hai.","Agle saal mere bhai ki shaadi hai.","Agle mahine meri behen ki shaadi hai."],"correctAnswer":"Agle mahine mere bhai ki shaadi hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kal hamare school ka annual function ___ .","options":["hai","hain","tha","hoga"],"correctAnswer":"hai"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Tomorrow is my mother''s birthday, we will bring cake.","wordBankItems":["Kal","meri","maa","ka","birthday","hai",",","hum","cake","laaenge","."],"correctAnswer":"Kal meri maa ka birthday hai , hum cake laaenge ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aashirvaad means?","options":["blessing","greeting","invitation","gift"],"correctAnswer":"blessing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000005f',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about Indian culture and customs in Hindi","Use yahan ka riwaz X hai for local customs","Describe traditions and practices"],"explanation":{"intro":"Indian culture and customs vocabulary covers traditions, social norms, and how to describe cultural practices in Hindi.","culturalNote":"Key Indian customs: joote utaarna (taking off shoes before entering home or temple — universal in India), bade logo ke pair chhuna (touching elders'' feet as a sign of respect — called pranam or charan sparsh), atithi devo bhava (the guest is like God — famous Indian hospitality principle from Taittiriya Upanishad), bhojan pehle khaao (eat first, then talk business — guests always fed before discussions). Gestures: head wobble (side-to-side nod means yes, I understand, OK — confusing to foreigners), namaste gesture (hands pressed together), beckoning (palm-down wave — opposite of Western palm-up). Caste system (jati = caste — complex social hierarchy — constitutional protections for lower castes — reservations/quotas — ongoing social reform). Dowry (dahej — illegal but persists — serious social problem). Arranged marriages (arranged marriage) — the dominant form — but love marriages increasing. Red color auspicious. White for mourning. Coconut (nariyal) for puja — auspicious symbol. Sindoor (red powder in parting of hair for married Hindu women)."},"examples":[{"sentence":"Yahan ghar mein jaane se pehle joote utaarne ka riwaz hai.","english":"Here the custom is to take off shoes before entering the home."},{"sentence":"India mein bade logo ke pairon ko chhoo kar pranam kiya jaata hai.","english":"In India touching the feet of elders is done as a greeting/sign of respect."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe Indian cultural customs and traditions in Hindi."}}',
'{"items":[{"word":"riwaz","translation":"custom/tradition","transliteration":"riwaz","pronunciation":"ri-WAAJ","example":"purana riwaz"},{"word":"parampara","translation":"tradition/heritage","transliteration":"parampara","pronunciation":"pa-RAM-pa-ra","example":"parampara nibhaana"},{"word":"aadar","translation":"respect","transliteration":"aadar","pronunciation":"AA-dar","example":"aadar dena"},{"word":"atithi","translation":"guest","transliteration":"atithi","pronunciation":"a-TI-thi","example":"atithi ka swagat"},{"word":"pranam","translation":"respectful greeting/bow","transliteration":"pranam","pronunciation":"pra-NAAM","example":"pranam karna"},{"word":"tejasawi","translation":"auspicious/sacred","transliteration":"tejasawi","pronunciation":"te-JAS-wi","example":"shubh tejasawi"}]}',
'{"title":"Yahan X karne ka riwaz hai — Here the custom is to do X","pattern":"Yahan X karne ka riwaz hai = Here the custom is to do X. Karne = oblique infinitive of karna. Ka = possessive (of doing). Riwaz = custom (masculine). Hai = is. General custom statement: X ka riwaz hai (the custom of X exists). India mein X karne ka riwaz hai = In India it is the custom to do X.","explanation":"Custom description: X karne ka riwaz hai. Karne = oblique infinitive (karna → karne). ka agrees with riwaz (masculine singular). Alternative: X karna aadar ka nishaan hai (doing X is a sign of respect). Passive-like constructions for customs: X kiya jaata hai (X is done — passive) — very common in describing customs. India mein joote utaare jaate hain (in India shoes are removed). This impersonal passive (kiya jaata hai) is the most neutral way to describe social practices.","examples":[{"sentence":"Dilli mein mehmano ko pehle chai pilaayi jaati hai.","english":"In Delhi guests are first served tea."},{"sentence":"India mein shaadi mein laal rang ka bahut mahatva hai.","english":"In India the colour red has great importance at weddings."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"riwaz means?","options":["custom/tradition","culture","religion","festival"],"correctAnswer":"custom/tradition"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Here the custom is to take off shoes before entering the home.","options":["Yahan ghar mein jaane se pehle joote utaarne ka riwaz hai.","Yahan temple mein jaane se pehle joote utaarne ka riwaz hai.","India mein ghar mein jaane se pehle joote utaarne ka riwaz hai.","Yahan ghar mein jaane ke baad joote utaarne ka riwaz hai."],"correctAnswer":"Yahan ghar mein jaane se pehle joote utaarne ka riwaz hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"India mein shaadi mein laal rang ka bahut ___ hai.","options":["mahatva","mahatva hota","riwaz","parampara"],"correctAnswer":"mahatva"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In Delhi guests are first served tea.","wordBankItems":["Dilli","mein","mehmano","ko","pehle","chai","pilaayi","jaati","hai","."],"correctAnswer":"Dilli mein mehmano ko pehle chai pilaayi jaati hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"pranam means?","options":["respectful greeting/bow","thank you","blessing","farewell"],"correctAnswer":"respectful greeting/bow"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000060',1,'APPROVED','PUBLISHED',
'{"objectives":["Make extended polite requests in Hindi","Use zara X kijiye for polite requests","Respond to requests graciously"],"explanation":{"intro":"Extended polite requests covers a fuller range of ways to make requests — gentle, formal, and very polite — and how to respond in Hindi.","culturalNote":"Politeness register in Hindi: very formal: kripaya X kijiye (please do X — Sanskrit kripaya = please). Polite: X kijiye (please do X — formal imperative). Semi-formal: X karein (please do X — less formal). Colloquial: zara X karo (please do X — casual). Adding zara (just/a moment): zara ruko (just wait a moment), zara bataiye (please just tell me). Please/sorry/thank you frequency: these are used less frequently between close friends and family in Hindi than in English — overuse can feel distant or strange. Formal vs informal registers: Indian languages have very clear registers — addressing a stranger or elder requires more formal language. Code-switching (mixing Hindi-English) is very common in urban India: ''kya aap mujhe ek favour kar sakte hain?'' (can you do me a favour?)."},"examples":[{"sentence":"Zara ek glass paani dijiye.","english":"Please give me a glass of water (gentle request)."},{"sentence":"Kripaya thoda dhire boliye, mujhe samajh nahi aa raha.","english":"Please speak a little slower, I''m not understanding."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can make polite requests at different formality levels in Hindi."}}',
'{"items":[{"word":"zara","translation":"just/a little (softener for requests)","transliteration":"zara","pronunciation":"ZA-ra","example":"zara batao"},{"word":"kripaya","translation":"please (formal)","transliteration":"kripaya","pronunciation":"kri-PA-ya","example":"kripaya aiye"},{"word":"dhire","translation":"slowly/gently","transliteration":"dhire","pronunciation":"DHI-re","example":"dhire bolna"},{"word":"dohrana","translation":"to repeat","transliteration":"dohrana","pronunciation":"doh-RAA-na","example":"dohraiye"},{"word":"samajhna","translation":"to understand","transliteration":"samajhna","pronunciation":"sa-MAJH-na","example":"samajh gaya"},{"word":"mazboori","translation":"compulsion/helplessness","transliteration":"mazboori","pronunciation":"maz-BOO-ree","example":"mazboori mein"}]}',
'{"title":"Zara X kijiye / kijiye please — gentle polite request (zara as softener)","pattern":"Zara X kijiye = Please (just) do X (gentle/soft request). Zara (zara) = just, a moment, a little (request softener — makes requests less direct). Kijiye = very polite imperative of karna. Zara ruk jaiye (please just stop). Zara bataaiye (please just tell me). Adding please: please X kijiye or zara X kijiye (both work — zara is more natural Indian Hindi).","explanation":"Softening requests with zara: adding ''zara'' before a request makes it gentler and more natural. Without zara: bataaiye (tell me — polite but slightly direct). With zara: zara bataaiye (please just tell me — much softer). Common patterns: zara suniye (please listen), zara dekhiye (please have a look), zara ruk jaiye (please just wait). In Indian service encounters (hotel, restaurant, shop), zara + kijiye is the polite go-to. Very gentle: zara si der ke liye (just for a little while). Responding: zaroor (certainly), abhi karta hoon (I''ll do it right now), haan bilkul (yes absolutely).","examples":[{"sentence":"Zara menu dikhaaiye.","english":"Please show me the menu."},{"sentence":"Kripaya thoda aur aawaaz barhaaiye.","english":"Please turn up the volume a little more."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"zara means?","options":["just/a little (softener)","please","politely","quickly"],"correctAnswer":"just/a little (softener)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Please speak a little slower, I''m not understanding.","options":["Kripaya thoda dhire boliye, mujhe samajh nahi aa raha.","Kripaya thoda zyada boliye, mujhe samajh nahi aa raha.","Zara thoda dhire boliye, mujhe samajh nahi aa raha.","Kripaya thoda dhire boliye, mujhe sunai nahi de raha."],"correctAnswer":"Kripaya thoda dhire boliye, mujhe samajh nahi aa raha."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Zara menu ___ .","options":["dikhaaiye","dikhao","dekho","dekh"],"correctAnswer":"dikhaaiye"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please give me a glass of water.","wordBankItems":["Zara","ek","glass","paani","dijiye","."],"correctAnswer":"Zara ek glass paani dijiye ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"samajhna means?","options":["to understand","to explain","to ask","to know"],"correctAnswer":"to understand"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000061',1,'APPROVED','PUBLISHED',
'{"objectives":["Use frequency expressions in Hindi","Use kabhi-kabhi, aksar, hamesha for frequency","Describe how often you do things"],"explanation":{"intro":"Frequency expressions vocabulary covers how to say always, often, sometimes, rarely, and never in Hindi — essential for describing habits and routines.","culturalNote":"Frequency in Indian life: hamesha (always — from Persian hama = all + sha = time), aksar (often — from Arabic akthar = more), kabhi-kabhi (sometimes — kabhi = ever/sometimes + kabhi = ever/sometimes — doubled for ''sometimes''), kabhee-kabhaar (rarely), kabhi nahi (never). Time management: Indian Standard Time (IST) is also jokingly called IST = Indian Stretchable Time — referring to the relaxed attitude toward punctuality in informal contexts. However, professional contexts have become much more punctual. Hamesha late rehna (always being late) is a stereotype that Indians themselves joke about. Ek baar (once), do baar (twice), teen baar (three times) — baar = times/occasions."},"examples":[{"sentence":"Main hamesha subah chai peeta hoon.","english":"I always drink tea in the morning."},{"sentence":"Wo kabhi-kabhi late aata hai.","english":"He sometimes comes late."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can use frequency expressions to describe how often I do things in Hindi."}}',
'{"items":[{"word":"hamesha","translation":"always","transliteration":"hamesha","pronunciation":"ha-ME-sha","example":"hamesha karna"},{"word":"aksar","translation":"often/usually","transliteration":"aksar","pronunciation":"AK-sar","example":"aksar jaana"},{"word":"kabhi-kabhi","translation":"sometimes","transliteration":"kabhi-kabhi","pronunciation":"KAB-hi KAB-hi","example":"kabhi-kabhi milna"},{"word":"kabhi nahi","translation":"never","transliteration":"kabhi nahi","pronunciation":"KAB-hi na-HEE","example":"kabhi nahi karta"},{"word":"roz","translation":"daily/every day","transliteration":"roz","pronunciation":"roz","example":"roz karna"},{"word":"baar","translation":"time/occasion","transliteration":"baar","pronunciation":"baar","example":"ek baar"}]}',
'{"title":"Frequency adverbs — hamesha, aksar, kabhi-kabhi, kabhi nahi position in sentence","pattern":"Frequency adverbs go before the main verb: Subject + frequency + verb. Main hamesha subah chai peeta hoon (I always drink morning tea). Wo kabhi-kabhi late aata hai (He sometimes comes late). Main kabhi nahi jhooth bolta (I never lie). Position: frequency adverb immediately before the verb phrase (before the tense helper hoon/hai/hain).","explanation":"Frequency adverb order in Hindi: frequency adverb is placed right before the verb (or verb phrase). Scale: hamesha (always) > aksar (often) > kabhi-kabhi (sometimes) > kabhee-kabhaar (rarely) > kabhi nahi (never). Time frequency: roz (daily), har hafte (every week), mahine mein ek baar (once a month), saal mein do baar (twice a year). Questions: tum kitni baar? (how often do you?), aap aksar X karte hain? (do you often do X?). Combining: main aksar lekin kabhi-kabhi nahi karta (I often do it but sometimes I don''t).","examples":[{"sentence":"Wo aksar library mein padhta hai.","english":"He often studies in the library."},{"sentence":"Hum log saal mein ek baar pahad jaate hain.","english":"We go to the mountains once a year."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"aksar means?","options":["often/usually","always","sometimes","rarely"],"correctAnswer":"often/usually"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I always drink tea in the morning.","options":["Main hamesha subah chai peeta hoon.","Main aksar subah chai peeta hoon.","Main kabhi-kabhi subah chai peeta hoon.","Main roz subah coffee peeta hoon."],"correctAnswer":"Main hamesha subah chai peeta hoon."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Hum log saal mein ek ___ pahad jaate hain.","options":["baar","din","hafte","mahine"],"correctAnswer":"baar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He sometimes comes late.","wordBankItems":["Wo","kabhi-kabhi","late","aata","hai","."],"correctAnswer":"Wo kabhi-kabhi late aata hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hamesha means?","options":["always","often","sometimes","never"],"correctAnswer":"always"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000062',1,'APPROVED','PUBLISHED',
'{"objectives":["Tell a simple story in Hindi","Use past tense sequence for narrative","Connect events with phir, tab, jab"],"explanation":{"intro":"Telling a simple story covers how to narrate a sequence of events in the past using time connectors in Hindi.","culturalNote":"Story-telling in India: oral tradition (shrutiparamparaa = oral tradition — basis of Vedas) is foundational to Indian culture. Grandmother stories (dadi/naani ki kahaaniyan) — children''s bedtime stories. Folk tales (lok-kathaen) — Panchatantra (300 BCE — animal fables), Jataka tales (Buddhist), Arabian Nights (Indian origin — 1001 Nights). Modern: Bollywood film scripts — narrative-heavy, emotional arcs. Podcasts (podcasts) — Indian storytelling podcasts growing. The story structure in Hindi often uses: ek baar (once upon a time), phir (then/next), aakhir mein (finally/in the end). Climax (charamseema), twist (twist), moral (seekh = lesson). Ramayana and Mahabharata — the world''s longest epics — foundational to Indian cultural narrative vocabulary."},"examples":[{"sentence":"Ek din main bazar gaya. Wahan ek purani dost mili. Phir hum saath chai pine baithe.","english":"One day I went to the market. There I met an old friend. Then we sat together to have tea."},{"sentence":"Jab main ghar pahuncha, tab baarish shuru ho gayi.","english":"When I reached home, then the rain began."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can tell a simple story using past tense and narrative connectors in Hindi."}}',
'{"items":[{"word":"ek din","translation":"one day","transliteration":"ek din","pronunciation":"ek din","example":"ek din ki baat hai"},{"word":"jab","translation":"when","transliteration":"jab","pronunciation":"jab","example":"jab aaya"},{"word":"tab","translation":"then/at that time","transliteration":"tab","pronunciation":"tab","example":"tab gaya"},{"word":"aakhir mein","translation":"finally/at the end","transliteration":"aakhir mein","pronunciation":"AA-khir mein","example":"aakhir mein"},{"word":"hua","translation":"happened/occurred","transliteration":"hua","pronunciation":"hua","example":"kya hua"},{"word":"mila/mili","translation":"met/found (m/f)","transliteration":"mila/mili","pronunciation":"MI-la/MI-li","example":"dost mila"}]}',
'{"title":"Jab X, tab Y — When X, then Y (temporal subordinate clause)","pattern":"Jab X, tab Y = When X, (then) Y. Jab = when (temporal conjunction). Tab = then (correlative — often paired with jab). X = time-based condition clause (past/present/future). Y = main clause (what happens when X). Jab main pahuncha, tab baarish shuru hui = When I arrived, then the rain started.","explanation":"Jab...tab construction: correlative pair for temporal conditions. Jab (when) introduces the when-clause, tab (then) introduces the result. Both clauses usually in past tense for narratives. Tab can be dropped in informal speech: jab main pahuncha, baarish shuru hui. Jab X hoga, tab Y hoga = When X will happen, then Y will happen (future). Jab X tha, tab Y tha = When X was, Y was (past state). Very common in storytelling and conditional/temporal Hindi.","examples":[{"sentence":"Jab main bahar nikla, tab andhera ho chuka tha.","english":"When I stepped out, it had already become dark."},{"sentence":"Jab usne gaana sunaya, tab sab khamosh ho gaye.","english":"When she sang, everyone became silent."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"aakhir mein means?","options":["finally/at the end","at the beginning","in the middle","sometimes"],"correctAnswer":"finally/at the end"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"When I reached home, then the rain began.","options":["Jab main ghar pahuncha, tab baarish shuru ho gayi.","Jab main bazar pahuncha, tab baarish shuru ho gayi.","Jab main ghar pahunchi, tab baarish shuru ho gayi.","Jab main ghar pahuncha, tab dhoop nikali."],"correctAnswer":"Jab main ghar pahuncha, tab baarish shuru ho gayi."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Jab usne gaana sunaya, tab sab khamosh ho ___ .","options":["gaye","gaya","gayi","gaye the"],"correctAnswer":"gaye"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: One day I went to the market and met an old friend.","wordBankItems":["Ek","din","main","bazar","gaya","aur","wahan","ek","purani","dost","mili","."],"correctAnswer":"Ek din main bazar gaya aur wahan ek purani dost mili ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"jab means?","options":["when","then","after","before"],"correctAnswer":"when"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000063',1,'APPROVED','PUBLISHED',
'{"objectives":["Review key grammar structures from Hindi A1","Practice hoon/hai/hain, tha/thi/the, karna hai, sak na","Consolidate the A1 grammar toolkit"],"explanation":{"intro":"A1 grammar review consolidates the most important structures covered across the A1 level — verb forms, postpositions, and key constructions.","culturalNote":"Hindi A1 grammar toolkit summary: (1) To be — present: hoon/hai/hain/ho; past: tha/thi/the/theen. (2) Habitual present: karta/karti/karte hai/hain (does/do). (3) Continuous present: kar raha/rahi/rahe hoon/hai/hain (is/am/are doing). (4) Past transitive (ergative): ne + verb agreeing with object. (5) Past intransitive: verb agreeing with subject (no ne). (6) Future: karunga/karogi/karenge. (7) Obligation: mujhe karna hai / chahiye. (8) Ability/permission: sakna. (9) Key postpositions: mein, par, se, ko, tak, ke liye, ke paas, ke saath, ke baad, se pehle. (10) Key connectors: kyunki, isliye, lekin, aur, ya, jab, tab, pehle, phir. These 10 categories cover the core of A1 Hindi. Moving to A2, you will encounter reported speech, subjunctive, and more complex narrative tenses."},"examples":[{"sentence":"Main roz subah uthta hoon, chai peeta hoon aur daftar jaata hoon.","english":"Every morning I get up, drink tea, and go to the office."},{"sentence":"Kal maine khaana banaya aur phir film dekhi.","english":"Yesterday I made food and then watched a film."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I can use all key Hindi A1 grammar structures confidently."}}',
'{"items":[{"word":"hoon","translation":"am (1st person singular)","transliteration":"hoon","pronunciation":"hoon","example":"main theek hoon"},{"word":"karta/karti","translation":"does/do (habitual m/f)","transliteration":"karta/karti","pronunciation":"KAR-ta/KAR-ti","example":"roz karta hoon"},{"word":"ne","translation":"ergative agent marker (past transitive)","transliteration":"ne","pronunciation":"ne","example":"maine kiya"},{"word":"chahiye","translation":"should/needed (impersonal)","transliteration":"chahiye","pronunciation":"chaa-HI-ye","example":"karna chahiye"},{"word":"sakna","translation":"can/be able to (modal)","transliteration":"sakna","pronunciation":"SAK-na","example":"bol sakta hoon"},{"word":"ke saath","translation":"with/together with","transliteration":"ke saath","pronunciation":"ke SAATH","example":"dost ke saath"}]}',
'{"title":"A1 grammar review — 10 core structures consolidated","pattern":"(1) main X hoon = I am X. (2) main X karta hoon = I do X (habitual). (3) main X kar raha hoon = I am doing X (continuous). (4) maine X kiya = I did X (past transitive). (5) main X gaya = I went X (past intransitive). (6) main X karunga = I will do X (future). (7) mujhe X karna hai = I need to do X. (8) main X kar sakta hoon = I can do X. (9) X ke baad / se pehle = after/before X. (10) kyunki X, isliye Y = because X, therefore Y.","explanation":"Full A1 grammar toolkit: all 10 patterns are now available for use in Hindi A1. They cover: identity, habitual action, ongoing action, past action (split ergative), future, obligation, ability, temporal relations, and logical connectors. The split ergative (past transitive uses ne, intransitive does not) is the most challenging feature of A1 Hindi — the key is identifying whether the verb is transitive or intransitive. All other A1 structures follow fairly regular patterns. Moving forward in A2, new topics: reported speech (usne kaha ki...), conditional (agar...to), and more complex tenses.","examples":[{"sentence":"Agar tum theek se padhoge, to pariksha zaroor paas karoge.","english":"If you study properly, you will surely pass the exam."},{"sentence":"Usne kaha ki wo kal aayega.","english":"He said that he would come tomorrow."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"ne is used with which type of verb in past tense?","options":["transitive verbs","intransitive verbs","all verbs","no verbs"],"correctAnswer":"transitive verbs"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Every morning I get up, drink tea, and go to the office.","options":["Main roz subah uthta hoon, chai peeta hoon aur daftar jaata hoon.","Main kabhi-kabhi subah uthta hoon, chai peeta hoon aur daftar jaata hoon.","Main roz subah uthta hoon, coffee peeta hoon aur daftar jaata hoon.","Wo roz subah uthta hai, chai peeta hai aur daftar jaata hai."],"correctAnswer":"Main roz subah uthta hoon, chai peeta hoon aur daftar jaata hoon."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kal maine khaana ___ aur phir film dekhi.","options":["banaya","banayi","banaye","bana"],"correctAnswer":"banaya"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I can speak Hindi a little.","wordBankItems":["Main","thodi","Hindi","bol","sakta","hoon","."],"correctAnswer":"Main thodi Hindi bol sakta hoon ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"chahiye means?","options":["should/needed (impersonal)","want","need","must"],"correctAnswer":"should/needed (impersonal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000064',1,'APPROVED','PUBLISHED',
'{"objectives":["Complete Hindi A1 with a comprehensive review","Use a wide range of A1 vocabulary and structures","Reflect on progress and prepare for A2"],"explanation":{"intro":"Hindi A1 final milestone lesson consolidates everything learned across 100 lessons — vocabulary, grammar, cultural knowledge — and previews what is ahead in A2.","culturalNote":"Completing Hindi A1: you can now greet, introduce yourself, describe your family and home, talk about daily routines, navigate markets, shops, hospitals, and stations, express your opinions and preferences, understand Indian cultural practices, use the past, present and future tenses, and hold basic conversations on a wide range of everyday topics. You know about India''s incredible diversity — 1.4 billion people, 22 official languages, 29 states, thousands of years of history. Hindi A2 will build on this foundation: more complex sentences, reported speech, the subjunctive mood, richer vocabulary for work, travel, health, and relationships, and deeper cultural insights. Congratulations on completing A1 — aap bahut acche hain! (You are very good!) — ab A2 ki taraf badhein! (Now advance towards A2!)"},"examples":[{"sentence":"Ab main Hindi mein thoda-bahut bol sakta hoon aur samajh sakta hoon.","english":"Now I can speak and understand Hindi a little."},{"sentence":"Hindi seekhna bahut dilchasp hai kyunki isme ek poori duniya hai.","english":"Learning Hindi is very interesting because there is a whole world within it."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I have completed Hindi A1 — I can communicate in Hindi on a wide range of everyday topics."}}',
'{"items":[{"word":"seekhna","translation":"to learn","transliteration":"seekhna","pronunciation":"SEEKH-na","example":"Hindi seekhna"},{"word":"pratham","translation":"first/primary","transliteration":"pratham","pronunciation":"PRA-tham","example":"pratham kadam"},{"word":"aage badhna","translation":"to move forward/progress","transliteration":"aage badhna","pronunciation":"AA-ge BADH-na","example":"aage badho"},{"word":"mehanat","translation":"hard work/effort","transliteration":"mehnat","pronunciation":"MEH-nat","example":"mehanat karna"},{"word":"safalta","translation":"success","transliteration":"safalta","pronunciation":"SA-fal-ta","example":"safalta milna"},{"word":"badhai","translation":"congratulations","transliteration":"badhai","pronunciation":"bad-HAA-ee","example":"badhai ho"}]}',
'{"title":"Ab main X kar sakta/sakti hoon — Now I can do X (ability statement for milestone)","pattern":"Ab main X kar sakta hoon (male) / sakti hoon (female) = Now I can do X. Ab = now. main = I. X kar = do X (verb stem). sakta/sakti hoon = can (modal ability). This is the celebratory construction for marking progress — ''now I can...'' — used at milestones, after completing a course, after learning a skill.","explanation":"Milestone ability construction: ab + main + activity + sakta/sakti hoon. Ab (ab) = now (marks change from before). Sakna = can (ability modal). Full range of abilities you now have in Hindi A1: Hindi bolna (speak Hindi), khud ko milvaana (introduce yourself), bazar mein kharidaari karna (shop at a market), directions poochhna (ask for directions), doctor se baat karna (talk to a doctor), train ticket kharidna (buy a train ticket), apne khyaalaat kehna (express your opinions). A2 will expand: longer conversations, reported speech, complex narratives.","examples":[{"sentence":"Ab main India mein safar kar sakta hoon.","english":"Now I can travel in India."},{"sentence":"Bahut mehnat ke baad ab main Hindi padh sakta hoon.","english":"After a lot of hard work, now I can read Hindi."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"badhai means?","options":["congratulations","blessing","thanks","greeting"],"correctAnswer":"congratulations"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Now I can speak and understand Hindi a little.","options":["Ab main Hindi mein thoda-bahut bol sakta hoon aur samajh sakta hoon.","Pehle main Hindi mein thoda-bahut bol sakta tha aur samajh sakta tha.","Ab main Hindi mein zyada bol sakta hoon aur samajh sakta hoon.","Ab main Hindi mein thoda-bahut bol sakti hoon aur samajh sakti hoon."],"correctAnswer":"Ab main Hindi mein thoda-bahut bol sakta hoon aur samajh sakta hoon."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bahut mehnat ke baad ab main Hindi padh ___ hoon.","options":["sakta","sakti","sakte","sakna"],"correctAnswer":"sakta"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Now I can travel in India.","wordBankItems":["Ab","main","India","mein","safar","kar","sakta","hoon","."],"correctAnswer":"Ab main India mein safar kar sakta hoon ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aage badhna means?","options":["to move forward/progress","to go back","to stop","to rest"],"correctAnswer":"to move forward/progress"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

